fn bin_search(a: &[i32], k: i32) -> bool {
    // We maintain the search interval as [lo, hi), half-open.
    let mut lo: usize = 0;
    let mut hi: usize = a.len();

    while lo < hi {
        // Avoid overflow by computing mid this way
        let mid = lo + (hi - lo) / 2;
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    false
}

